@import "tailwindcss";

@theme {
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'DM Sans', system-ui, sans-serif;
  --color-cream: #F5F2ED;
  --color-ink: #1A1A1A;
  --color-warm: #C27B5A;
  --color-sage: #8B9D83;
  --color-sand: #D4C5B2;
  --color-terracotta: #C2856A;
}

body {
  margin: 0;
  background: #F5F2ED;
  color: #1A1A1A;
}

/* Navigation */
.nav-link {
  position: relative;
  font-size: 0.875rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #1A1A1A;
  text-decoration: none;
  transition: opacity 0.3s;
}
.nav-link:hover {
  opacity: 0.5;
}
.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 1px;
  background: #1A1A1A;
}

/* Mobile menu overlay */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: #F5F2ED;
  z-index: 50;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}
.mobile-overlay.open {
  opacity: 1;
  pointer-events: auto;
}
.mobile-overlay .mobile-nav-link {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 2.5rem;
  font-weight: 600;
  color: #1A1A1A;
  text-decoration: none;
  margin: 1rem 0;
  transition: opacity 0.3s;
}
.mobile-overlay .mobile-nav-link:hover {
  opacity: 0.5;
}

/* Hamburger button */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  z-index: 60;
  position: relative;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: #1A1A1A;
  transition: transform 0.3s, opacity 0.3s;
}
.hamburger.open span:nth-child(1) {
  transform: translateY(6.5px) rotate(45deg);
}
.hamburger.open span:nth-child(2) {
  opacity: 0;
}
.hamburger.open span:nth-child(3) {
  transform: translateY(-6.5px) rotate(-45deg);
}
@media (max-width: 768px) {
  .hamburger {
    display: flex;
  }
  .desktop-nav {
    display: none;
  }
}

/* Marquee */
.marquee-row {
  display: flex;
  overflow: hidden;
  user-select: none;
  gap: 0;
}
.marquee-track {
  display: flex;
  gap: 2rem;
  flex-shrink: 0;
  min-width: 100%;
  animation-play-state: running;
}
.marquee-row:hover .marquee-track {
  animation-play-state: paused;
}

/* Editorial styles */
.editorial-body {
  font-size: 1.125rem;
  line-height: 1.8;
  color: #2A2A2A;
}
.editorial-body p {
  margin-bottom: 1.5em;
}
.editorial-body .drop-cap::first-letter {
  float: left;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 4.5rem;
  line-height: 0.8;
  padding-right: 0.25em;
  color: #1A1A1A;
}

/* Section label */
.section-label {
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #8B7355;
  margin-bottom: 1.5rem;
}

/* Client grid card */
.client-card {
  border-bottom: 1px solid #D4C5B2;
  padding-bottom: 1.5rem;
}
.client-card h3 {
  font-family: 'Playfair Display', Georgia, serif;
  font-weight: 700;
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
  color: #1A1A1A;
}
.client-card p {
  font-size: 0.875rem;
  line-height: 1.6;
  color: #5A5A5A;
}

/* Media showcase blocks */
.media-block {
  aspect-ratio: 16/10;
  border-radius: 2px;
}

