export interface NavLink {
  label: string
  href: string
}

export const NAV_LINKS: NavLink[] = [
  { label: 'Volta.', href: 'index.html' },
  { label: 'Neweno', href: 'neweno.html' },
  { label: 'Services', href: 'services.html' },
  { label: 'Clients', href: 'clients.html' },
  { label: 'Contact', href: 'contact.html' },
]

export function renderHeader(currentPage: string): string {
  const links = NAV_LINKS.map((link) => {
    const isHome = link.label === 'Volta.'
    const isActive = link.href === currentPage || (currentPage === 'index.html' && link.label === 'Volta.')
    const cls = isHome ? 'nav-link logo' : `nav-link${isActive ? ' active' : ''}`
    return `<a href="${link.href}" class="${cls}">${link.label}</a>`
  }).join('')

  return `
    <header class="w-full max-w-[1400px] mx-auto px-8 md:px-16 py-8 flex items-center justify-between">
      <div class="desktop-nav flex items-center gap-8">
        ${links}
      </div>
      <button class="hamburger" id="hamburger" aria-label="Toggle menu">
        <span></span>
        <span></span>
        <span></span>
      </button>
    </header>
    <div class="mobile-overlay" id="mobileMenu">
      ${NAV_LINKS.map((l) => `<a href="${l.href}" class="mobile-nav-link">${l.label === 'Volta.' ? 'Home' : l.label}</a>`).join('')}
    </div>
  `
}

export function initMobileMenu(): void {
  const hamburger = document.getElementById('hamburger')
  const overlay = document.getElementById('mobileMenu')

  if (!hamburger || !overlay) return

  let isOpen = false

  hamburger.addEventListener('click', () => {
    isOpen = !isOpen
    hamburger.classList.toggle('open', isOpen)
    overlay.classList.toggle('open', isOpen)
    document.body.style.overflow = isOpen ? 'hidden' : ''
  })

  overlay.querySelectorAll('a').forEach((link) => {
    link.addEventListener('click', () => {
      isOpen = false
      hamburger.classList.remove('open')
      overlay.classList.remove('open')
      document.body.style.overflow = ''
    })
  })
}

