export function renderMarquee(): string {
  const row1 = ['Nexora', 'Pinnacle', 'Orbis', 'Kinetic', 'Lumina', 'Helix']
  const row2 = ['Streamline', 'Beacon', 'Prism', 'Zenith', 'Forge', 'Catalyst']
  const row3 = ['Vertex', 'Horizon', 'Atlas', 'Meridian', 'Crest', 'Ember']

  function buildRow(names: string[], direction: 'left' | 'right'): string {
    const dup = [...names, ...names, ...names, ...names]
    const items = dup.map((n) => `<span class="text-2xl md:text-3xl font-serif font-semibold italic whitespace-nowrap text-[#1A1A1A] opacity-80">${n} <span class="text-[#C27B5A] mx-1">◦</span></span>`).join(' ')
    return `
      <div class="marquee-row py-3 border-b border-[#D4C5B2]">
        <div class="marquee-track marquee-${direction}" style="animation: scroll-${direction} 40s linear infinite;">
          ${items}
        </div>
        <div class="marquee-track marquee-${direction}" style="animation: scroll-${direction} 40s linear infinite;" aria-hidden="true">
          ${items}
        </div>
      </div>
    `
  }

  return `
    <style>
      @keyframes scroll-left {
        0% { transform: translateX(0); }
        100% { transform: translateX(-50%); }
      }
      @keyframes scroll-right {
        0% { transform: translateX(-50%); }
        100% { transform: translateX(0); }
      }
      .marquee-left {
        animation: scroll-left 40s linear infinite !important;
      }
      .marquee-right {
        animation: scroll-right 40s linear infinite !important;
      }
    </style>
    <section class="w-full overflow-hidden py-12 md:py-20">
      <div class="section-label text-center">Selected Clients</div>
      ${buildRow(row1, 'left')}
      ${buildRow(row2, 'right')}
      ${buildRow(row3, 'left')}
    </section>
  `
}

